import React from 'react';
import { Navigate } from 'react-router-dom';
import { useAuth } from '../components/utils/auth';

const PublicRoute = ({ children }) => {
  const { role } = useAuth(); // Get the user's role from the context

  // If the user is logged in (i.e., role is not null), redirect to home
  if (role) {
    return <Navigate to="/home" replace />;
  }

  // Ensure children is defined before returning
  return children ? children : null; // If not logged in, render the child components (Login/Register)
};

export default PublicRoute;
